import json,re,statistics,collections
from pathlib import Path
by={}
for p in sorted(Path('/workspace/results/ppo_countdown/val_generations').glob('*.jsonl'),key=lambda p:int(p.stem)):
 rs=[json.loads(s) for s in p.read_text().splitlines()]; by[int(p.stem)]=rs
 trunc=[r for r in rs if r['response_length']==512]; complete=[r for r in rs if r['response_length']<512]
 print('\nSTEP',p.stem,'score',sum(r['score'] for r in rs)/len(rs),'truncated',len(trunc)/len(rs),'nontrunc_score',sum(r['score'] for r in complete)/max(1,len(complete)), 'end-token',sum('<|im_end|>' in r['output'] for r in rs),'answer-tag',sum('<answer>' in r['output'] for r in rs),'answer+score0',sum(r['score']==0 and '<answer>' in r['output'] for r in rs),'score+trunc',sum(r['score']>0 and r['response_length']==512 for r in rs))
 print('length mean/median',statistics.mean(r['response_length'] for r in rs),statistics.median(r['response_length'] for r in rs))
 if int(p.stem)>0:
  base=by[0]; a=[r['score'] for r in base]; b=[r['score'] for r in rs]
  print('vs baseline: baseline-only',sum(x>y for x,y in zip(a,b)),'current-only',sum(y>x for x,y in zip(a,b)),'both-correct',sum(x>0 and y>0 for x,y in zip(a,b)))
 print('Most common outputs (truncated prefix compressed):')
 for text,n in collections.Counter(r['output'][:120] for r in rs).most_common(5): print(n,repr(text))
print('\nSTEP 29 SELECTED COMPLETE INCORRECT OUTPUTS')
for i,r in enumerate(by[29]):
 if r['score']==0 and r['response_length']<512:
  print('INDEX',i,'LEN',r['response_length'],'OUTPUT',repr(r['output'][:1600]))
  if i>100: break
