python -I - <<'PY'
import json
from pathlib import Path
rs=[json.loads(s) for s in Path('/workspace/results/ppo_countdown/metrics.jsonl').read_text().splitlines()]
for step in [3,4,24]:
 rec=[r for r in rs if r['step']==step]
 print('\nSTEP',step)
 for r in rec:
  d=r['data']
  if 'rollout/advantages' in d: print('abs advantage',d['rollout/advantages'])
  if 'grpo_metrics/no_grad' in d: print('no_grad',d['grpo_metrics/no_grad'])
  if 'train/grad_norm' in d and 'train/loss' in d: print('actor grad',d['train/grad_norm'])
PY

